CREATE TABLE IF NOT EXISTS trips(id text PRIMARY KEY, version integer NOT NULL DEFAULT 1, config jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bases(id text PRIMARY KEY,trip_id text NOT NULL REFERENCES trips(id),name text NOT NULL,position integer NOT NULL,config jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS properties(id text PRIMARY KEY,name text NOT NULL,base_id text NOT NULL REFERENCES bases(id),canonical_url text UNIQUE NOT NULL,style text NOT NULL DEFAULT 'unknown',pinned boolean NOT NULL DEFAULT false,hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS units(id text PRIMARY KEY,property_id text NOT NULL REFERENCES properties(id),name text NOT NULL,identity_confirmed boolean NOT NULL DEFAULT false,uncertainties text[] NOT NULL DEFAULT '{}',UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS listings(id text PRIMARY KEY,property_id text NOT NULL REFERENCES properties(id),unit_id text REFERENCES units(id),provider text NOT NULL,source_id text,original_url text UNIQUE NOT NULL,last_attempt timestamptz,last_success timestamptz,outcome text NOT NULL DEFAULT 'unsupported');
CREATE TABLE IF NOT EXISTS evidence(id text PRIMARY KEY,unit_id text REFERENCES units(id),property_id text NOT NULL REFERENCES properties(id),field text NOT NULL,value jsonb NOT NULL,scope text NOT NULL CHECK(scope IN ('property','unit','rate')),source_url text NOT NULL,retrieved_at timestamptz NOT NULL,confidence text NOT NULL,attribution text NOT NULL,manual boolean NOT NULL DEFAULT false,snippet text CHECK(length(snippet)<=300));
CREATE TABLE IF NOT EXISTS scans(id text PRIMARY KEY,trip_id text NOT NULL REFERENCES trips(id),config_version integer NOT NULL,config_snapshot jsonb NOT NULL,idempotency_key text UNIQUE NOT NULL,trigger text NOT NULL,status text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,lease_until timestamptz NOT NULL,reserved_microusd integer NOT NULL DEFAULT 0,queries integer NOT NULL DEFAULT 0,details integer NOT NULL DEFAULT 0,offers integer NOT NULL DEFAULT 0,discovered integer NOT NULL DEFAULT 0,error text);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_scan ON scans(trip_id) WHERE status='running';
CREATE TABLE IF NOT EXISTS provider_tasks(id text PRIMARY KEY,scan_id text NOT NULL REFERENCES scans(id),provider text NOT NULL,kind text NOT NULL,subject text NOT NULL,outcome text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),error text);
CREATE TABLE IF NOT EXISTS observations(id text PRIMARY KEY,listing_id text NOT NULL REFERENCES listings(id),scan_id text NOT NULL REFERENCES scans(id),outcome text NOT NULL,availability text NOT NULL DEFAULT 'unknown',observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS offers(id text PRIMARY KEY,unit_id text NOT NULL REFERENCES units(id),listing_id text NOT NULL REFERENCES listings(id),scan_id text NOT NULL REFERENCES scans(id),config_version integer NOT NULL,check_in date NOT NULL,check_out date NOT NULL,adults integer NOT NULL,currency text NOT NULL,rate_key text NOT NULL,conditions jsonb NOT NULL,availability text NOT NULL CHECK(availability IN ('available','unavailable','unknown')),outcome text NOT NULL CHECK(outcome IN ('success','blocked','error','unsupported')),base_cents integer,fees_cents integer,taxes_cents integer,total_cents integer,unknown_components text[] NOT NULL DEFAULT '{}',cancellation_deadline timestamptz,cancellation_timezone text,booking_url text,observed_at timestamptz NOT NULL DEFAULT now(),CHECK(total_cents IS NULL OR cardinality(unknown_components)=0));
CREATE TABLE IF NOT EXISTS favorites(unit_id text PRIMARY KEY REFERENCES units(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS selections(base_id text PRIMARY KEY REFERENCES bases(id),unit_id text NOT NULL REFERENCES units(id),booked boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notes(id text PRIMARY KEY,unit_id text NOT NULL REFERENCES units(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS changes(id text PRIMARY KEY,scan_id text REFERENCES scans(id),config_version integer NOT NULL,unit_id text REFERENCES units(id),kind text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS evidence_unit ON evidence(unit_id,field);
CREATE INDEX IF NOT EXISTS offer_lookup ON offers(unit_id,config_version,observed_at DESC);
CREATE INDEX IF NOT EXISTS scans_started ON scans(started_at DESC);
CREATE OR REPLACE FUNCTION immutable_observation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable observation'; END $$;
CREATE TRIGGER immutable_offers BEFORE UPDATE OR DELETE ON offers FOR EACH ROW EXECUTE FUNCTION immutable_observation();
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON evidence FOR EACH ROW EXECUTE FUNCTION immutable_observation();
CREATE TRIGGER immutable_observations BEFORE UPDATE OR DELETE ON observations FOR EACH ROW EXECUTE FUNCTION immutable_observation();
